import pandas as pd
import numpy as np
from sklearn.ensemble import RandomForestClassifier
from sklearn.multiclass import OneVsRestClassifier
from sklearn.model_selection import train_test_split
from sklearn.metrics import roc_auc_score
import os
import warnings
from collections import defaultdict

warnings.filterwarnings("ignore")


def main():
    # Ensure submission directory exists
    os.makedirs("./submission", exist_ok=True)

    # 1. Load Folds
    folds = {}
    with open("./input/essential_data/CVfolds_2.txt", "r") as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) >= 2:
                try:
                    rec_id = int(parts[0])
                    fold_val = int(parts[1])
                    folds[rec_id] = fold_val
                except ValueError:
                    continue

    # 2. Load Labels
    labels = {}
    with open("./input/essential_data/rec_labels_test_hidden.txt", "r") as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 2:
                continue
            try:
                rec_id = int(parts[0])
            except ValueError:
                continue
            if parts[1] != "?":
                valid_labels = []
                for x in parts[1:]:
                    try:
                        valid_labels.append(int(x))
                    except ValueError:
                        pass
                labels[rec_id] = valid_labels

    # 3. Load Histogram Features (100 dims)
    # Initialize all rec_ids from folds to ensure we don't miss any
    all_rec_ids = sorted(folds.keys())
    hist_features = {rid: np.zeros(100) for rid in all_rec_ids}

    with open("./input/supplemental_data/histogram_of_segments.txt", "r") as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 3:
                continue
            try:
                rec_id = int(parts[0])
                features = [float(x) for x in parts[2:]]
                if rec_id in hist_features:
                    hist_features[rec_id] = np.array(features)
            except ValueError:
                continue

    # 4. Load Segment Features (38 dims per segment)
    segment_data = defaultdict(list)
    with open("./input/supplemental_data/segment_features.txt", "r") as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 3:
                continue
            try:
                rec_id = int(parts[0])
                features = [float(x) for x in parts[2:]]
                segment_data[rec_id].append(features)
            except ValueError:
                continue

    # 5. Aggregate Segment Features
    seg_stats_features = {rid: [] for rid in all_rec_ids}
    seg_counts = {rid: 0 for rid in all_rec_ids}

    for rid in all_rec_ids:
        if rid in segment_data and len(segment_data[rid]) > 0:
            data = np.array(segment_data[rid])  # Shape: (n_segments, 38)
            seg_counts[rid] = len(data)
            # Compute stats: mean, std, min, max, median along axis 0
            stats = []
            for i in range(38):
                col = data[:, i]
                stats.extend(
                    [
                        np.mean(col),
                        np.std(col),
                        np.min(col),
                        np.max(col),
                        np.median(col),
                    ]
                )
            seg_stats_features[rid] = np.array(stats)
        else:
            seg_counts[rid] = 0
            seg_stats_features[rid] = np.zeros(38 * 5)  # 190 zeros

    # 6. Combine Features
    X = []
    y = []
    train_indices = []
    test_indices = []

    for idx, rid in enumerate(all_rec_ids):
        # Combine: 100 hist + 190 seg_stats + 1 count
        feat_vec = np.concatenate(
            [hist_features[rid], seg_stats_features[rid], [seg_counts[rid]]]
        )
        X.append(feat_vec)

        if folds[rid] == 0:
            train_indices.append(idx)
            # Prepare label vector
            label_vec = [0] * 19
            if rid in labels:
                for sp in labels[rid]:
                    if 0 <= sp < 19:
                        label_vec[sp] = 1
            y.append(label_vec)
        else:
            test_indices.append(idx)

    X = np.array(X)
    y = np.array(y)
    X_train = X[train_indices]
    y_train = y[train_indices]
    X_test = X[test_indices]
    test_rec_ids = [all_rec_ids[i] for i in test_indices]

    # 7. Train/Val Split (80/20 on training fold)
    X_tr, X_val, y_tr, y_val = train_test_split(
        X_train, y_train, test_size=0.2, random_state=42
    )

    # 8. Train Model
    model = OneVsRestClassifier(
        RandomForestClassifier(
            n_estimators=100, class_weight="balanced", random_state=42, n_jobs=-1
        )
    )
    model.fit(X_tr, y_tr)

    # 9. Validate
    y_val_pred = model.predict_proba(X_val)
    valid_aucs = []
    for i in range(y_val.shape[1]):
        y_true_col = y_val[:, i]
        y_score_col = y_val_pred[:, i]
        if len(np.unique(y_true_col)) > 1:
            valid_aucs.append(roc_auc_score(y_true_col, y_score_col))

    if len(valid_aucs) > 0:
        auc = np.mean(valid_aucs)
        print(f"Validation AUC-ROC: {auc:.4f}")
    else:
        print("Validation AUC-ROC: Could not compute")
        auc = 0.0

    # 10. Retrain on Full Training Data for Submission
    model.fit(X_train, y_train)
    y_test_pred = model.predict_proba(X_test)

    # 11. Save Submission
    submission_rows = []
    for i, rec_id in enumerate(test_rec_ids):
        for species in range(19):
            id_val = rec_id * 100 + species
            prob = y_test_pred[i, species]
            submission_rows.append([id_val, prob])

    submission_df = pd.DataFrame(submission_rows, columns=["Id", "Probability"])
    submission_df = submission_df.sort_values(by="Id").reset_index(drop=True)
    submission_df.to_csv("./submission/submission.csv", index=False)
    print(f"Submission saved with {len(submission_df)} rows")


if __name__ == "__main__":
    main()
